import Foundation
import Testing
@testable import JICompute

/// Parity tests for the energy-balance port (`app/nutrition/energy.py`).
///
/// Fixture is generated by `HealthTraining/scripts/parity/gen_golden_energy.py`
/// — ground truth is the Python module executed by the interpreter. Never edit
/// the fixture by hand; run `HealthTraining/scripts/regen_goldens.py`.
///
/// 1,472 cases in ONE `cases` array, tagged by `fn`:
/// trailingTdee 170 · deriveGoals 430 · energyAvailability 204 ·
/// correctedTdee 304 · classifyDeficit 48 · computeDailyBalance 316.
/// Each golden case is one test case, so the count `swift test` prints IS the
/// golden count.

// MARK: - Fixture plumbing

/// Strictness helpers for the energy fixture.
///
/// `StrictCase` (GoldenLoader) only guards the TOP-level keys of a case object
/// (`fn`/`input`/`output`). The energy fixture nests its real payload one level
/// down, so every nested object re-checks its own key set here: an extra key
/// means the Swift port is behind the generator, a missing key means the
/// generator changed shape — both are errors, never a silent pass.
enum EnergyFixture {
    static let file = "energy.golden"

    enum Failure: Error, CustomStringConvertible {
        case unknownKeys(group: String, keys: [String])
        case missingKeys(group: String, keys: [String])
        case unknownFunction(String)

        var description: String {
            switch self {
            case .unknownKeys(let group, let keys):
                return "energy.golden \(group) has unknown key(s) \(keys.sorted().joined(separator: ", ")) — the Swift port is behind the generator"
            case .missingKeys(let group, let keys):
                return "energy.golden \(group) is missing key(s) \(keys.sorted().joined(separator: ", ")) — the generator changed shape"
            case .unknownFunction(let fn):
                return "energy.golden has a case for unknown function \"\(fn)\" — the Swift port is behind the generator"
            }
        }
    }

    /// The nested object's key set must equal `allowed`, exactly.
    static func check(_ container: KeyedDecodingContainer<AnyKey>, allowed: Set<String>, group: String) throws {
        let present = Set(container.allKeys.map(\.stringValue))
        let unknown = present.subtracting(allowed)
        guard unknown.isEmpty else { throw Failure.unknownKeys(group: group, keys: Array(unknown)) }
        let missing = allowed.subtracting(present)
        guard missing.isEmpty else { throw Failure.missingKeys(group: group, keys: Array(missing)) }
    }

    static func input(_ decoder: Decoder, allowed: Set<String>, group: String) throws -> KeyedDecodingContainer<AnyKey> {
        let root = try decoder.container(keyedBy: AnyKey.self)
        let input = try root.nestedContainer(keyedBy: AnyKey.self, forKey: AnyKey("input"))
        try check(input, allowed: allowed, group: "\(group).input")
        return input
    }

    static func output(_ decoder: Decoder, allowed: Set<String>, group: String) throws -> KeyedDecodingContainer<AnyKey> {
        let root = try decoder.container(keyedBy: AnyKey.self)
        let output = try root.nestedContainer(keyedBy: AnyKey.self, forKey: AnyKey("output"))
        try check(output, allowed: allowed, group: "\(group).output")
        return output
    }

    /// Scalar (or null) `output` of a case whose function returns one value.
    static func scalarOutput<T: Decodable>(_ decoder: Decoder, as type: T.Type) throws -> T? {
        let root = try decoder.container(keyedBy: AnyKey.self)
        return try root.decodeIfPresent(T.self, forKey: AnyKey("output"))
    }
}

/// IEEE-754-blind equality is not enough: `0.0 == -0.0` is true, and the
/// fixture contains a genuine `-0.0` (`deficitPctRaw` on 2026-01-05). Compare
/// bit patterns, the `Object.is` the TS oracle test uses.
private func energySame(_ got: Double?, _ want: Double?) -> Bool {
    switch (got, want) {
    case (nil, nil): return true
    case (let g?, let w?): return g.bitPattern == w.bitPattern
    default: return false
    }
}

// MARK: - Cases

struct EnergyTrailingTdeeCase: Decodable, Sendable, CustomTestStringConvertible {
    let trackedIntakes: [Double]
    let wStart7d: Double?
    let wEnd7d: Double?
    let spanDays: Int
    let expected: Double?

    init(from decoder: Decoder) throws {
        let input = try EnergyFixture.input(
            decoder,
            allowed: ["trackedIntakes", "wStart7d", "wEnd7d", "spanDays"],
            group: "trailingTdee"
        )
        trackedIntakes = try input.decode([Double].self, forKey: AnyKey("trackedIntakes"))
        wStart7d = try input.decodeIfPresent(Double.self, forKey: AnyKey("wStart7d"))
        wEnd7d = try input.decodeIfPresent(Double.self, forKey: AnyKey("wEnd7d"))
        spanDays = try input.decode(Int.self, forKey: AnyKey("spanDays"))
        expected = try EnergyFixture.scalarOutput(decoder, as: Double.self)
    }

    var testDescription: String { "trailingTdee(n=\(trackedIntakes.count), span=\(spanDays))" }
}

