struct EnergyDailyBalanceCase: Decodable, Sendable, CustomTestStringConvertible {
    let date: String
    let kcalConsumed: Double?
    let totalKcal: Double?
    let mealsLogged: Int?
    let kcalBurnedActive: Double?
    let tdeeEmpirical: Double?
    let expected: DailyEnergyBalance

    init(from decoder: Decoder) throws {
        let input = try EnergyFixture.input(
            decoder,
            allowed: ["date", "kcalConsumed", "totalKcal", "mealsLogged", "kcalBurnedActive", "tdeeEmpirical"],
            group: "computeDailyBalance"
        )
        date = try input.decode(String.self, forKey: AnyKey("date"))
        kcalConsumed = try input.decodeIfPresent(Double.self, forKey: AnyKey("kcalConsumed"))
        totalKcal = try input.decodeIfPresent(Double.self, forKey: AnyKey("totalKcal"))
        mealsLogged = try input.decodeIfPresent(Int.self, forKey: AnyKey("mealsLogged"))
        kcalBurnedActive = try input.decodeIfPresent(Double.self, forKey: AnyKey("kcalBurnedActive"))
        tdeeEmpirical = try input.decodeIfPresent(Double.self, forKey: AnyKey("tdeeEmpirical"))

        let output = try EnergyFixture.output(
            decoder,
            allowed: [
                "date", "kcalConsumed", "tdeeRaw", "tdeeCorrected", "deficitRaw",
                "deficitCorrected", "deficitPctRaw", "deficitPctCorrected", "deficitClass", "mealsLogged",
            ],
            group: "computeDailyBalance"
        )
        expected = DailyEnergyBalance(
            date: try output.decode(String.self, forKey: AnyKey("date")),
            kcalConsumed: try output.decodeIfPresent(Double.self, forKey: AnyKey("kcalConsumed")),
            tdeeRaw: try output.decodeIfPresent(Double.self, forKey: AnyKey("tdeeRaw")),
            tdeeCorrected: try output.decodeIfPresent(Double.self, forKey: AnyKey("tdeeCorrected")),
            deficitRaw: try output.decodeIfPresent(Double.self, forKey: AnyKey("deficitRaw")),
            deficitCorrected: try output.decodeIfPresent(Double.self, forKey: AnyKey("deficitCorrected")),
            deficitPctRaw: try output.decodeIfPresent(Double.self, forKey: AnyKey("deficitPctRaw")),
            deficitPctCorrected: try output.decodeIfPresent(Double.self, forKey: AnyKey("deficitPctCorrected")),
            deficitClass: try output.decodeIfPresent(DeficitClass.self, forKey: AnyKey("deficitClass")),
            mealsLogged: try output.decodeIfPresent(Int.self, forKey: AnyKey("mealsLogged"))
        )
    }

    var testDescription: String { "computeDailyBalance(\(date), \(kcalConsumed as Double?), \(totalKcal as Double?))" }
}

/// One heterogeneous `cases` array: every entry carries its `fn` tag and the
/// payload shape that tag implies. An unknown tag fails the load — a golden
/// file that grew a seventh function must not shrink to six silently.
struct EnergyCase: GoldenCase {
    static let allowedKeys: Set<String> = ["fn", "input", "output"]

    enum Payload: Sendable {
        case trailingTdee(EnergyTrailingTdeeCase)
        case deriveGoals(EnergyDeriveGoalsCase)
        case energyAvailability(EnergyAvailabilityCase)
        case correctedTdee(EnergyCorrectedTdeeCase)
        case classifyDeficit(EnergyClassifyDeficitCase)
        case computeDailyBalance(EnergyDailyBalanceCase)
    }

    let payload: Payload

    init(from decoder: Decoder) throws {
        let root = try decoder.container(keyedBy: AnyKey.self)
        switch try root.decode(String.self, forKey: AnyKey("fn")) {
        case "trailingTdee": payload = .trailingTdee(try EnergyTrailingTdeeCase(from: decoder))
        case "deriveGoals": payload = .deriveGoals(try EnergyDeriveGoalsCase(from: decoder))
        case "energyAvailability": payload = .energyAvailability(try EnergyAvailabilityCase(from: decoder))
        case "correctedTdee": payload = .correctedTdee(try EnergyCorrectedTdeeCase(from: decoder))
        case "classifyDeficit": payload = .classifyDeficit(try EnergyClassifyDeficitCase(from: decoder))
        case "computeDailyBalance": payload = .computeDailyBalance(try EnergyDailyBalanceCase(from: decoder))
        case let other: throw EnergyFixture.Failure.unknownFunction(other)
        }
    }
}

enum EnergyGolden {
    /// Decoded once; the six `@Test(arguments:)` groups are views onto it.
    static let all = GoldenLoader.require(EnergyCase.self, file: EnergyFixture.file, group: "cases")

    static let trailingTdeeCases: [EnergyTrailingTdeeCase] = all.compactMap {
        if case .trailingTdee(let c) = $0.payload { return c } else { return nil }
    }
    static let deriveGoalsCases: [EnergyDeriveGoalsCase] = all.compactMap {
        if case .deriveGoals(let c) = $0.payload { return c } else { return nil }
    }
    static let energyAvailabilityCases: [EnergyAvailabilityCase] = all.compactMap {
        if case .energyAvailability(let c) = $0.payload { return c } else { return nil }
    }
    static let correctedTdeeCases: [EnergyCorrectedTdeeCase] = all.compactMap {
        if case .correctedTdee(let c) = $0.payload { return c } else { return nil }
    }
    static let classifyDeficitCases: [EnergyClassifyDeficitCase] = all.compactMap {
        if case .classifyDeficit(let c) = $0.payload { return c } else { return nil }
    }
    static let computeDailyBalanceCases: [EnergyDailyBalanceCase] = all.compactMap {
        if case .computeDailyBalance(let c) = $0.payload { return c } else { return nil }
    }
}

// MARK: - Tests

@Test(arguments: EnergyGolden.trailingTdeeCases)
func energyTrailingTdeeMatchesPython(_ c: EnergyTrailingTdeeCase) {
    let got = Energy.trailingTdee(c.trackedIntakes, wStart7d: c.wStart7d, wEnd7d: c.wEnd7d, spanDays: c.spanDays)
    #expect(energySame(got, c.expected), "trailingTdee: got \(got as Double?), want \(c.expected as Double?)")
}

@Test(arguments: EnergyGolden.deriveGoalsCases)
func energyDeriveGoalsMatchesPython(_ c: EnergyDeriveGoalsCase) {
    let got = Energy.deriveGoals(tdee: c.tdee, leanKg: c.leanKg, weightKg: c.weightKg)
    #expect(energySame(got.intakeKcal, c.intakeKcal), "intakeKcal: got \(got.intakeKcal), want \(c.intakeKcal)")
    #expect(energySame(got.proteinG, c.proteinG), "proteinG: got \(got.proteinG as Double?), want \(c.proteinG as Double?)")
    #expect(energySame(got.fatG, c.fatG), "fatG: got \(got.fatG as Double?), want \(c.fatG as Double?)")
    #expect(energySame(got.carbsG, c.carbsG), "carbsG: got \(got.carbsG as Double?), want \(c.carbsG as Double?)")
}

@Test(arguments: EnergyGolden.energyAvailabilityCases)
func energyAvailabilityMatchesPython(_ c: EnergyAvailabilityCase) {
    let got = Energy.energyAvailability(intakeKcal: c.intakeKcal, exerciseKcal: c.exerciseKcal, leanKg: c.leanKg)
    #expect(energySame(got, c.expected), "energyAvailability: got \(got as Double?), want \(c.expected as Double?)")
}

@Test(arguments: EnergyGolden.correctedTdeeCases)
func energyCorrectedTdeeMatchesPython(_ c: EnergyCorrectedTdeeCase) {
    let got = Energy.correctedTdee(totalKcal: c.totalKcal, kcalBurnedActive: c.kcalBurnedActive)
    #expect(energySame(got, c.expected), "correctedTdee: got \(got as Double?), want \(c.expected as Double?)")
}

@Test(arguments: EnergyGolden.classifyDeficitCases)
func energyClassifyDeficitMatchesPython(_ c: EnergyClassifyDeficitCase) {
    let got = Energy.classifyDeficit(c.deficitPct)
    #expect(got == c.expected, "classifyDeficit(\(c.deficitPct as Double?)): got \(got as DeficitClass?), want \(c.expected as DeficitClass?)")
}

@Test(arguments: EnergyGolden.computeDailyBalanceCases)
func energyComputeDailyBalanceMatchesPython(_ c: EnergyDailyBalanceCase) {
    let got = Energy.computeDailyBalance(
        date: c.date,
        kcalConsumed: c.kcalConsumed,
        totalKcal: c.totalKcal,
        mealsLogged: c.mealsLogged,
        kcalBurnedActive: c.kcalBurnedActive,
        tdeeEmpirical: c.tdeeEmpirical
    )
    let want = c.expected
    #expect(got.date == want.date)
    #expect(energySame(got.kcalConsumed, want.kcalConsumed), "kcalConsumed: got \(got.kcalConsumed as Double?), want \(want.kcalConsumed as Double?)")
    #expect(energySame(got.tdeeRaw, want.tdeeRaw), "tdeeRaw: got \(got.tdeeRaw as Double?), want \(want.tdeeRaw as Double?)")
    #expect(energySame(got.tdeeCorrected, want.tdeeCorrected), "tdeeCorrected: got \(got.tdeeCorrected as Double?), want \(want.tdeeCorrected as Double?)")
    #expect(energySame(got.deficitRaw, want.deficitRaw), "deficitRaw: got \(got.deficitRaw as Double?), want \(want.deficitRaw as Double?)")
    #expect(energySame(got.deficitCorrected, want.deficitCorrected), "deficitCorrected: got \(got.deficitCorrected as Double?), want \(want.deficitCorrected as Double?)")
    #expect(energySame(got.deficitPctRaw, want.deficitPctRaw), "deficitPctRaw: got \(got.deficitPctRaw as Double?), want \(want.deficitPctRaw as Double?)")
    #expect(energySame(got.deficitPctCorrected, want.deficitPctCorrected), "deficitPctCorrected: got \(got.deficitPctCorrected as Double?), want \(want.deficitPctCorrected as Double?)")
    #expect(got.deficitClass == want.deficitClass, "deficitClass: got \(got.deficitClass as DeficitClass?), want \(want.deficitClass as DeficitClass?)")
    #expect(got.mealsLogged == want.mealsLogged, "mealsLogged: got \(got.mealsLogged as Int?), want \(want.mealsLogged as Int?)")
}
